CREATE TABLE public.bi_report_datasets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,code TEXT NOT NULL,name TEXT NOT NULL,domain TEXT NOT NULL,allowed_fields JSONB NOT NULL DEFAULT '[]',allowed_filters JSONB NOT NULL DEFAULT '[]',allowed_aggregations JSONB NOT NULL DEFAULT '[]',access_roles TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],sensitivity TEXT NOT NULL DEFAULT 'standard',active BOOLEAN NOT NULL DEFAULT true,UNIQUE(company_id,code));
CREATE TABLE public.bi_dashboard_layouts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,name TEXT NOT NULL,layout_type TEXT NOT NULL CHECK(layout_type IN('system','personal','department','executive')),owner_id UUID REFERENCES auth.users(id),department_id UUID,config JSONB NOT NULL DEFAULT '{}',active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.bi_scorecards(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,name TEXT NOT NULL,domain TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('department','company','executive')),owner_id UUID REFERENCES auth.users(id),active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE public.bi_scorecard_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,scorecard_id UUID NOT NULL REFERENCES public.bi_scorecards(id) ON DELETE CASCADE,kpi_id UUID NOT NULL REFERENCES public.bi_kpi_definitions(id) ON DELETE CASCADE,display_order INTEGER NOT NULL DEFAULT 0,drill_down_config JSONB NOT NULL DEFAULT '{}',UNIQUE(scorecard_id,kpi_id));
CREATE TABLE public.bi_data_quality_issues(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,domain TEXT NOT NULL,issue_type TEXT NOT NULL CHECK(issue_type IN('missing_required_data','invalid_reference','stale_source_data','duplicate_source_records','unmapped_category','incomplete_period')),details JSONB NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','acknowledged','resolved')),detected_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.bi_alerts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,alert_type TEXT NOT NULL CHECK(alert_type IN('kpi_critical','kpi_warning','stale_data','missing_target','failed_calculation','report_due','report_generation_failed','data_quality_issue')),severity TEXT NOT NULL CHECK(severity IN('info','warning','critical')),title TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}',acknowledged_at TIMESTAMPTZ,acknowledged_by UUID REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['bi_report_datasets','bi_dashboard_layouts','bi_scorecards','bi_scorecard_items','bi_data_quality_issues','bi_alerts'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);EXECUTE format('GRANT ALL ON public.%I TO service_role',t);EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (public.has_any_role(company_id,ARRAY[''admin'',''executive'',''managing_director'',''analyst'',''operations_manager'',''finance_manager'',''commercial_manager'',''fleet_manager'',''warehouse_manager'',''hr_manager'',''compliance_manager'',''procurement_manager'',''crm_manager'',''department_manager'',''viewer'']::public.app_role[]))',t||'_read',t);END LOOP;END $$;
